deployment.program:
import config_v1x5.aleo;

program alphaswap_v1x5.aleo;

struct ProtocolFee:
    collector as address;
    base_portion as u128;

record PrivateToken:
    owner as address.private;
    token as field.private;
    amount as u128.private;

struct TokenInfo:
    name as field;
    symbol as field;
    decimals as u8;
    total_supply as u128;
    admin as address;
    mintable as boolean;
    burnable as boolean;

struct Pair:
    reserve_a as u128;
    reserve_b as u128;
    last_k as u128;

struct AccountKeyData:
    token as field;
    user as address;

struct SwapApprovalKeyData:
    token as field;
    payer as address;
    spender as address;

struct PairKeyData:
    token_a as field;
    token_b as field;

struct TokenIdData:
    base as address;
    creator as address;
    salt as u128;

mapping account:
    key as field.public;
    value as u128.public;

mapping approvals:
    key as field.public;
    value as u128.public;

mapping tokens:
    key as field.public;
    value as TokenInfo.public;

mapping pairs:
    key as field.public;
    value as Pair.public;

function create_token:
    input r0 as field.public;
    input r1 as field.public;
    input r2 as u8.public;
    input r3 as u128.public;
    input r4 as address.public;
    input r5 as boolean.public;
    input r6 as boolean.public;
    input r7 as u128.public;
    assert.neq r0 0field;
    cast alphaswap_v1x5.aleo self.caller r7 into r8 as TokenIdData;
    hash.bhp256 r8 into r9 as field;
    async create_token self.caller r9 r0 r1 r2 r3 r4 r5 r6 into r10;
    output r10 as alphaswap_v1x5.aleo/create_token.future;

finalize create_token:
    input r0 as address.public;
    input r1 as field.public;
    input r2 as field.public;
    input r3 as field.public;
    input r4 as u8.public;
    input r5 as u128.public;
    input r6 as address.public;
    input r7 as boolean.public;
    input r8 as boolean.public;
    contains tokens[r1] into r9;
    assert.eq r9 false;
    cast r2 r3 r4 r5 r6 r7 r8 into r10 as TokenInfo;
    set r10 into tokens[r1];
    cast r1 r0 into r11 as AccountKeyData;
    hash.bhp256 r11 into r12 as field;
    set r10.total_supply into account[r12];

function transfer_public:
    input r0 as field.public;
    input r1 as address.public;
    input r2 as u128.public;
    cast r0 self.caller into r3 as AccountKeyData;
    hash.bhp256 r3 into r4 as field;
    cast r0 r1 into r5 as AccountKeyData;
    hash.bhp256 r5 into r6 as field;
    async transfer_public r0 r4 r6 r2 into r7;
    output r7 as alphaswap_v1x5.aleo/transfer_public.future;

finalize transfer_public:
    input r0 as field.public;
    input r1 as field.public;
    input r2 as field.public;
    input r3 as u128.public;
    contains tokens[r0] into r4;
    assert.eq r4 true;
    get account[r1] into r5;
    sub r5 r3 into r6;
    set r6 into account[r1];
    get.or_use account[r2] 0u128 into r7;
    add r7 r3 into r8;
    set r8 into account[r2];

function transfer_all_public:
    input r0 as field.public;
    input r1 as address.public;
    async transfer_all_public r0 self.caller r1 into r2;
    output r2 as alphaswap_v1x5.aleo/transfer_all_public.future;

finalize transfer_all_public:
    input r0 as field.public;
    input r1 as address.public;
    input r2 as address.public;
    contains tokens[r0] into r3;
    assert.eq r3 true;
    cast r0 r1 into r4 as AccountKeyData;
    hash.bhp256 r4 into r5 as field;
    cast r0 r2 into r6 as AccountKeyData;
    hash.bhp256 r6 into r7 as field;
    get account[r5] into r8;
    set 0u128 into account[r5];
    get.or_use account[r7] 0u128 into r9;
    add r9 r8 into r10;
    set r10 into account[r7];

