    assert.eq r0 r4.admin;
    ternary r2 false r4.mintable into r5;
    ternary r3 false r4.burnable into r6;
    cast r4.name r4.symbol r4.decimals r4.total_supply r4.admin r5 r6 into r7 as TokenInfo;
